"""Evaluation helpers.  Labels are consumed ONLY here, after anomaly scores
have been produced (paper Sec. 5.1; unsupervised protocol).

AUC-ROC: sklearn roc_auc_score.
AUC-PR : sklearn average_precision_score (ADBench convention), with the
         trapezoidal AUC of the precision-recall curve reported as a
         secondary variant.
"""

from __future__ import annotations

import numpy as np
from sklearn.metrics import (
    average_precision_score,
    precision_recall_curve,
    roc_auc_score,
)


def auc_roc(scores, y) -> float:
    return float(roc_auc_score(y, scores))


def auc_pr_average_precision(scores, y) -> float:
    return float(average_precision_score(y, scores))


def auc_pr_trapezoid(scores, y) -> float:
    precision, recall, _ = precision_recall_curve(y, scores)
    order = np.argsort(recall)
    return float(np.trapezoid(precision[order], recall[order]))


def evaluate_scores(scores, y) -> dict:
    """All metrics for one score vector; labels enter only at this point."""
    return {
        "auc_roc": auc_roc(scores, y),
        "auc_pr": auc_pr_average_precision(scores, y),
        "auc_pr_trapezoid": auc_pr_trapezoid(scores, y),
    }


def summarize(values) -> dict:
    v = np.asarray(list(values), dtype=np.float64)
    return {
        "mean": float(v.mean()),
        "std": float(v.std(ddof=1)) if len(v) > 1 else 0.0,
        "min": float(v.min()),
        "max": float(v.max()),
        "n": int(len(v)),
    }

